a <- commandArgs(FALSE); here <- dirname(normalizePath(sub('^--file=', '', a[grepl('^--file=', a)][1])))
source(file.path(here, '../scripts/fig_all.R'))
out <- Sys.getenv('OMICSTAT_MATRIX_TEST_OUT', file.path(tempdir(), 'matrix-semantics')); dir.create(out, recursive = TRUE, showWarnings = FALSE)
checks <- 0L; failed <- character()
check <- function(value, label) { checks <<- checks + 1L; if (isTRUE(value)) cat('PASS:', label, '\n') else { cat('FAIL:', label, '\n'); failed <<- c(failed, label) } }
bad <- function(expr, label, code = 'OS_') { e <- tryCatch({force(expr); ''}, error = conditionMessage); check(grepl(code, e, fixed = TRUE), label) }
meta <- function(p) attr(p, 'os_meta')
eq <- function(a,b) isTRUE(all.equal(a,b,check.attributes=TRUE,tolerance=1e-13))
m <- matrix(c(0,2,8,5, 1,3,5,7, 2,9,4,8, 6,8,3,11, 9,12,1,6, 10,14,4,15),4,dimnames=list(paste0('artificial_feature_',1:4),paste0('artificial_sample_',1:6)))
cd <- data.frame(sample=colnames(m),condition=rep(c('reference','treated'),each=3),time=rep(c('early','late','late'),2),stringsAsFactors=FALSE)
ft <- data.frame(feature_id=rownames(m),padj=c(.03,.01,.02,.2),log2fc=c(1,2,-2,0))
# Normalization orientation, parameters and raw values.
r <- os_matrix_normalize(m,'row_zscore'); c <- os_matrix_normalize(m,'col_zscore')
check(eq(r$values,t(scale(t(m)))[seq_len(nrow(m)),,drop=FALSE]), 'row z-score exactly follows feature axis')
check(eq(c$values,unclass(scale(m))[seq_len(nrow(m)),,drop=FALSE]), 'column z-score follows aggregate axis')
check(eq(r$values,t(os_matrix_normalize(t(m),'col_zscore')$values)), 'transpose switches axis without changing values')
check(identical(r$raw,m) && all(abs(rowMeans(r$values))<1e-12), 'raw values retained and z means are zero')
check(eq(r$definition$parameters$center,unname(rowMeans(m))), 'per-ID centers retained')
check(eq(r$definition$parameters$divisor,unname(apply(m,1,sd))), 'per-ID divisors retained')
big <- outer(seq_len(500),seq_len(1000),function(x,y) (x%%19)+y/100+sin(x+y))
dimnames(big)<-list(paste0('aggregate_',1:500),paste0('gene_',1:1000))
bz<-os_matrix_normalize(big,'col_zscore')
check(identical(dim(bz$values),c(500L,1000L)) && max(abs(colMeans(bz$values)))<1e-12 && max(abs(apply(bz$values,2,sd)-1))<1e-12,'500 aggregate by 1000 gene fixture normalizes each gene column')
check(eq(bz$values,t(os_matrix_normalize(t(big),'row_zscore')$values)),'500 by 1000 transposition preserves declared semantics')
rm(big,bz)
rms<-os_matrix_normalize(m+5,'row_rms')
check(all(rowMeans(rms$values)>0) && all(rms$definition$parameters$center==0), 'uncentered RMS is not called or computed as z-score')
check(eq(rms$values,t(scale(t(m+5),center=FALSE))[seq_len(nrow(m)),,drop=FALSE]),'RMS uses declared n-minus-one divisor')
mx<-os_matrix_normalize(m,'row_max')
check(all(apply(mx$values,1,max)==1) && identical(mx$raw,m),'max-normalization retains raw values and unit maximum')
rk<-os_matrix_normalize(m,'row_rank')
check(eq(rk$values,t(apply(m,1,rank))) && grepl('full supplied',rk$definition$formula),'rank uses full input and declared tie rule')
bad(os_matrix_normalize(-m,'row_max'),'signed max-normalization is refused')
zz<-m;zz[1,]<-0;zz[2,]<-4;zz[3,1]<-NA;zz[4,2]<-Inf
z<-os_matrix_normalize(zz,'row_zscore')
check(all(is.na(z$values)) && sum(z$state=='undefined_constant')==12,'constant rows are undefined, never fabricated zeros')
check(sum(z$state=='missing')==1 && sum(z$state=='infinite')==1,'original NA and Inf remain separate from undefined references')
check(all(os_matrix_normalize(zz[1,,drop=FALSE],'row_max')$state=='undefined_zero_divisor'),'zero max divisor is explicit')
check(all(os_matrix_normalize(m[,1,drop=FALSE],'row_zscore')$state=='undefined_single_sample'),'single sample z-score undefined')
# Direct distances, key-based joins and strict trees.
dm<-matrix(c(0,2,8,9, 2,0,4,7, 8,4,0,3, 9,7,3,0),4,dimnames=list(paste0('object_',1:4),paste0('object_',1:4)))
hc<-hclust(as.dist(dm),'complete'); ph<-os_heatmap(dm,'Supplied distance',matrix_kind='distance',unit='unknown')
tr<-meta(ph)$data$trees$rows$all
check(eq(unlist(tr$height),hc$height) && identical(unlist(tr$leaf_ids),hc$labels[hc$order]),'distance matrix is clustered directly once')
check(!eq(hc$height,hclust(dist(dm),'complete')$height),'nonuniform distance fixture detects a second distance transform')
check(identical(meta(ph)$data$row_order,meta(ph)$data$col_order),'distance row and column order identical')
pd<-os_heatmap(dm[c(3,1,4,2),c(2,4,1,3)],'Distance',matrix_kind='distance',cluster_rows=FALSE,cluster_cols=FALSE)
check(identical(meta(pd)$data$row_order,meta(pd)$data$col_order),'independently permuted distance axes rejoin by IDs')
v<-meta(pd)$data$display_values
check(all(v$value[v$row_id==v$col_id]==0),'distance diagonal remains exact zero by identity')
bad(os_heatmap(dm,'d',matrix_kind='distance',normalization='row_zscore'),'distance matrices cannot receive row normalization')
bad(os_heatmap(dm,'d',matrix_kind='distance',cluster_cols=FALSE),'inconsistent distance clustering axes rejected')
bad(os_heatmap(dm,'d',matrix_kind='distance',limits=c(1,10)),'distance palette must start at zero')
baddm<-dm;baddm[1,2]<-1;bad(os_heatmap(baddm,'d',matrix_kind='distance'),'asymmetric distance rejected')
baddm<-dm;diag(baddm)<-1;bad(os_heatmap(baddm,'d',matrix_kind='distance'),'nonzero distance diagonal rejected')
rot<-rev(hc$labels[hc$order]); pr<-os_heatmap(dm,'d',matrix_kind='distance',row_tree_rotation=rot)
check(identical(unlist(meta(pr)$data$row_order),rot) && identical(meta(pr)$data$row_order,meta(pr)$data$col_order),'supplied tree leaf rotation acts on both distance axes')
check(identical(meta(pr)$data$trees$rows$all$merge,tr$merge) && identical(meta(pr)$data$trees$rows$all$height,tr$height),'rotation preserves exact original merge and heights')
h2<-.os_tree_rotate(hc,rot);check(eq(cophenetic(h2),cophenetic(hc)),'rotation preserves cophenetic distances')
bad(.os_tree_rotate(hc,hc$labels[hc$order[c(1,3,2,4)]]),'topology-crossing leaf order rejected')
hbad<-hc;hbad$merge[1,1]<-3;bad(.os_validate_hclust(hbad,rownames(dm)),'future merge child rejected')
hbad<-hc;hbad$merge[1,2]<-hbad$merge[1,1];bad(.os_validate_hclust(hbad,rownames(dm)),'reused merge child rejected')
hbad<-hc;hbad$height[1]<-NA;bad(.os_validate_hclust(hbad,rownames(dm)),'nonfinite source tree height rejected')
hcustom<-hclust(dist(m), 'ward.D');p<-os_heatmap(m,'value',row_hclust=hcustom)
check(grepl('euclidean/ward.D',meta(p)$caption,fixed=TRUE) && !grepl('complete linkage',meta(p)$caption,fixed=TRUE),'supplied tree caption reports actual linkage rather than inventing complete')
# Display-only masks/clipping and inverse permutations.
tm<-m;tm[1,1]<-1.5;tm[2,1]<-1.5001
p0<-os_heatmap(tm,'score',unit='dimensionless'); p1<-os_heatmap(tm,'score',unit='dimensionless',display_mask_gt=1.5)
check(identical(meta(p0)$data$analysis_values,meta(p1)$data$analysis_values) && identical(meta(p0)$data$trees,meta(p1)$data$trees),'changing display mask does not change analysis values or clustering')
d<-meta(p1)$data$display_values
check(d$state[d$row_id==rownames(tm)[1]&d$col_id==colnames(tm)[1]]!='display_masked' && d$state[d$row_id==rownames(tm)[2]&d$col_id==colnames(tm)[1]]=='display_masked','strict threshold retains 1.5 and masks 1.5001')
check(meta(p1)$counts$display_masked_cells==sum(tm>1.5) && meta(p1)$counts$original_missing_cells==0,'masked and originally missing counts remain separate')
pc<-os_heatmap(m,'value','sequential',limits=c(1,10));check(meta(pc)$counts$clipped_cells==sum(m<1|m>10),'limits clipping counted once per cell')
check(all(meta(pc)$data$display_values$value>=1 & meta(pc)$data$display_values$value<=10) && identical(meta(pc)$data$source_values$value,as.vector(m)),'exported display uses actual clipped values while raw values are unchanged')
mp<-m;mp[1,2]<-NA;mp[3,4]<-Inf
bad(os_heatmap(mp,'value'),'nonfinite clustering requires explicit policy or source tree')
pn<-os_heatmap(mp,'value',missing_policy='no_cluster',row_order=rev(rownames(mp)),col_order=rev(colnames(mp)),cluster_rows=FALSE,cluster_cols=FALSE)
check(meta(pn)$counts$original_missing_cells==1 && meta(pn)$definition$matrix_contract$source_infinite_count==1,'missing and infinite inputs counted independently')
d<-meta(pn)$data$display_values; displayed<-matrix(d$value,nrow(mp),dimnames=list(unlist(meta(pn)$data$row_order),unlist(meta(pn)$data$col_order)))
recovered<-displayed[unlist(meta(pn)$data$permutations$row_inverse),unlist(meta(pn)$data$permutations$col_inverse)]
check(identical(is.na(recovered),!is.finite(mp)),'inverse permutations recover original unavailable mask by IDs')
check(identical(meta(pn)$definition$matrix_contract$nonfinite_cells$kind,'positive_infinity'),'infinite sign retained for lossless JSON reconstruction')
pp<-os_heatmap(mp,'value',row_hclust=hclust(dist(m)),col_hclust=hclust(dist(t(m))))
check(length(meta(pp)$data$trees$rows$all$leaf_ids)==4,'explicit source tree allows unavailable display values without imputation')
pa<-data.frame(group=rep('g',6),row.names=colnames(m));bad(os_heatmap(m,'v',col_annot=pa[-1,,drop=FALSE]),'missing annotation sample refused')
attr(pa,'row.names')<-rep('duplicate',6);bad(os_heatmap(m,'v',col_annot=pa),'duplicate annotation sample refused')
bad(os_heatmap(m,'v',row_split=setNames(rep('x',4),rep('same',4))),'duplicate split IDs refused')
# Gaps and explicit per-cell statistical states.
al<-os_align_matrices(list(m,m[c(3,1),,drop=FALSE]),'rows')
check(identical(rownames(al[[1]]),rownames(al[[2]])) && all(is.na(al[[2]][c(2,4),])),'missing linked rows get explicit ID gaps rather than row-number joins')
pag<-os_heatmap(al[[2]],'value',cluster_rows=FALSE,cluster_cols=FALSE)
check(meta(pag)$counts$source_states$unmeasured==12 && meta(pag)$counts$original_missing_cells==0,'inserted gaps do not inflate original missing count')
bad(os_align_matrices(list(m),'rows',rownames(m)[1:2]),'alignment cannot silently drop supplied IDs')
cells<-.os_matrix_table(m);cells$state<-as.vector(.os_matrix_states(m));cells$test_metric<-'adjusted_p';cells$threshold<-.05;cells$fit_id<-'artificial_fit'
cells$state[2]<-'reference';cells$state[3]<-'nonsignificant';cells$state[4]<-'failed';cells$state[5]<-'not_credible';cells$test_metric[5]<-'posterior_probability';cells$threshold[5]<-.95
ps<-os_heatmap(m,'effect',cluster_rows=FALSE,cluster_cols=FALSE,cell_metadata=cells[nrow(cells):1,])
check(identical(meta(ps)$data$source_values,cells),'cell metadata is restored by both IDs with exact value/state/test/threshold/fit')
check(all(c('reference','nonsignificant','failed','not_credible') %in% names(meta(ps)$definition$matrix_contract$state_legend)),'reference, significance, credibility and failure have separate visible keys')
cb<-cells;cb$row_id[1]<-'other';bad(os_heatmap(m,'v',cell_metadata=cb),'foreign cell key refused')
cb<-cells;cb$value[1]<-99;bad(os_heatmap(m,'v',cell_metadata=cb),'cell metadata cannot replace raw values')
# Ordered axes and fixed palettes.
keys<-setNames(c(500,100,750,250,1000,1500),colnames(m));pt<-os_heatmap(m,'v',col_axis_role='time',col_axis_keys=keys)
check(identical(unlist(meta(pt)$data$col_order),names(sort(keys))),'numeric time keys rather than labels determine default time order')
check(identical(meta(pt)$data$clustering$cols,'none'),'time axis is not clustered by default')
w<-character();pc<-withCallingHandlers(os_heatmap(m,'v',col_axis_role='time',col_axis_keys=keys,cluster_cols=TRUE),warning=function(e){w<<-c(w,conditionMessage(e));invokeRestart('muffleWarning')})
check(any(grepl('OS_FIG_ORDER_SEMANTICS',w)) && identical(meta(pc)$definition$matrix_contract$col_axis$original_keys,keys),'explicitly clustered time warns and keeps original time keys')
bad(os_heatmap(m,'v',col_axis_role='time'),'time axes without original numeric keys refused')
pconst<-os_heatmap(m*0+5,'constant','sequential',cluster_rows=FALSE,cluster_cols=FALSE)
check(all(is.finite(unlist(meta(pconst)$encodings$fill$limits))) && isTRUE(meta(pconst)$definition$matrix_contract$display_constant),'constant positive matrix has finite palette and explicit constant state')
pos<-os_heatmap(m+10,'positive','sequential');check(eq(unlist(meta(pos)$encodings$fill$limits),range(m+10)),'positive minimum and maximum map to actual palette endpoints')
# Top selection and distinct aggregation order.
pa<-os_top_heatmap(m,ft,cd,'condition',n=3,cluster_cols=FALSE)
pb<-suppressWarnings(os_top_heatmap(m,ft,cd,'condition',n=3,cluster_cols=TRUE))
check(identical(meta(pa)$definition$top_feature_selection$rank_order_ids,as.list(c(rownames(m)[2:3],rownames(m)[1]))),'top features retain adjusted-P rank and exact stable IDs')
check(grepl('condition then sample ID',meta(pa)$caption,fixed=TRUE) && grepl('columns by hierarchical clustering',meta(pb)$caption,fixed=TRUE),'top heatmap captions follow actual column ordering choice')
check(grepl('not unsupervised',meta(pa)$caption,fixed=TRUE),'selected feature heatmap discloses selection bias')
a<-os_top_heatmap(m,ft,cd,'condition',n=3,col_unit='condition_average',aggregation_order='zscore_then_mean')
b<-os_top_heatmap(m,ft,cd,'condition',n=3,col_unit='condition_average',aggregation_order='mean_then_zscore')
check(!eq(meta(a)$data$analysis_values$value,meta(b)$data$analysis_values$value),'z-score then mean and mean then z-score produce distinct calculations')
check(meta(a)$counts$n_source_samples==6 && meta(a)$counts$n_display_columns==2 && identical(unlist(meta(a)$definition$aggregation$n_replicates),c(reference=3L,treated=3L)),'condition averages retain source sample IDs and replicate counts')
check(identical(meta(a)$definition$aggregation$independent_unit,'unknown'),'replicate count does not invent independence')
pd<-os_sample_distance(m,cd,'condition',annotation_cols=c('condition','time'),preprocessing='blind')
check(all(c('condition','time') %in% names(meta(pd)$data$annotations$cols)) && nrow(meta(pd)$data$annotations$cols)==6,'sample distance carries multiple keyed annotation tracks')
check(meta(pd)$counts$n_samples==6 && meta(pd)$counts$n_features==4 && grepl('Preprocessing: blind',meta(pd)$caption,fixed=TRUE),'distance sample/feature counts and blind preprocessing remain distinct')
m8<-cbind(m,artificial_sample_7=m[,1]+.4,artificial_sample_8=m[,2]+.7)
cd8<-data.frame(sample=colnames(m8),condition=rep(c('a','b'),each=4),time=rep(c('early','late'),4))
p8<-os_sample_distance(m8,cd8,'condition',annotation_cols=c('condition','time'))
check(length(unique(unlist(meta(p8)$data$row_order)))==8 && length(unique(unlist(meta(p8)$data$col_order)))==8,'eight samples each occur once despite repeated condition/time labels')
cb<-cells;cb$test_metric[5]<-'adjusted_p';bad(os_heatmap(m,'v',cell_metadata=cb),'posterior credibility cannot be relabelled from adjusted P')
bad(os_heatmap(m,'v',normalization='row_zscore',unit='seconds'),'z-score cannot carry the raw time unit')
pu<-os_heatmap(m,'Runtime',normalization='row_zscore',source_unit='seconds')
check(meta(pu)$definition$matrix_contract$unit=='dimensionless' && meta(pu)$definition$matrix_contract$source_unit=='seconds' && grepl('row zscore',meta(pu)$encodings$fill$title,fixed=TRUE),'normalization exposes transformed and raw units and colourbar label')
dense<-matrix(rep(as.vector(m),75),300,6,dimnames=list(paste0('invented_dense_gene_',1:300),colnames(m)))
denseft<-data.frame(feature_id=rownames(dense),padj=seq_len(300)/301)
dp<-os_top_heatmap(dense,denseft,cd,'condition',n=270,missing_policy='no_cluster')
check(length(meta(dp)$data$feature_ids)==270 && nrow(meta(dp)$data$selected_feature_table)==270 && grepl('gene-level values',meta(dp)$caption,fixed=TRUE),'dense 270-feature view retains full feature table and avoids pixel-level quantitative claims')
# Guide, axis, entity and linked-row guards.
h<-os_heatmap(m,'value','sequential',unit='seconds',quantity='runtime',cluster_rows=FALSE,cluster_cols=FALSE)
walk_plots<-function(p) { if(!inherits(p,'patchwork')) return(list(p)); result<-unlist(lapply(p$patches$plots,walk_plots),recursive=FALSE); last<-p;class(last)<-setdiff(class(last),'patchwork');last$patches<-NULL;c(result,list(last)) }
body<-Filter(function(p)is.numeric(p$data$value) && all(c('row','col')%in%names(p$data)),walk_plots(h))[[1]]
actual_ticks<-ggplot2::ggplot_build(body)$plot$scales$get_scales('fill')$get_breaks()
check(eq(unname(actual_ticks),unname(unlist(meta(h)$notes$panel_contract$guides$value$ticks))),'guide contract ticks equal the actual rendered scale, not a separate pretty-break guess')
co<-os_compose(list(h,h),collect_guides=TRUE,linked_rows=TRUE)
check(isTRUE(meta(co)$definition$composition$effective) && meta(co)$data$n_panels==2,'identical heatmap guide contracts collect and nested plots each keep one panel')
count_guides<-function(g) { if(inherits(g,'gtable')) sum(g$layout$name=='guides')+sum(vapply(g$grobs,count_guides,0)) else if(inherits(g,'gTree')) sum(vapply(as.list(g$children),count_guides,0)) else 0 }
grDevices::cairo_pdf(file.path(out,'guide-count.pdf'),family=os_font_family())
actual_guide_count<-count_guides(patchwork::patchworkGrob(co));grDevices::dev.off()
check(isTRUE(meta(co)$definition$composition$shared_legend_rendered) && actual_guide_count==1,'nested compatible heatmaps actually render one shared guide rather than duplicate wrapped legends')
hm<-os_heatmap(m,'value','sequential',unit='milliseconds',quantity='runtime',cluster_rows=FALSE,cluster_cols=FALSE)
bad(os_compose(list(h,hm),collect_guides=TRUE),'different matrix units cannot share a guide')
hm<-os_heatmap(m+2,'value','sequential',unit='seconds',quantity='runtime',cluster_rows=FALSE,cluster_cols=FALSE)
bad(os_compose(list(h,hm),collect_guides=TRUE),'different continuous limits cannot share a guide')
hm<-os_heatmap(m[4:1,],'value','sequential',unit='seconds',quantity='runtime',cluster_rows=FALSE,cluster_cols=FALSE)
bad(os_compose(list(h,hm),linked_rows=TRUE),'linked rows cannot be matched by position across different ID orders')
praw<-ggplot2::ggplot(data.frame(x=1:3,y=2:4,id=c('one','two','three')),ggplot2::aes(x,y,colour=id))+ggplot2::geom_point()+ggplot2::scale_colour_manual(values=c(one='#0072B2',two='#D55E00',three='#009E73'))+ggplot2::scale_x_continuous(limits=c(0,4),breaks=0:4)+ggplot2::scale_y_continuous(limits=c(0,5),breaks=0:5)
g<-list(group=list(kind='discrete',aesthetic='colour',entity_type='artificial condition',values=list(one='#0072B2',two='#D55E00',three='#009E73')))
axes<-list(x=list(quantity='visit',unit='index',transform='identity',limits=c(0,4),ticks=0:4),y=list(quantity='score',unit='dimensionless',transform='identity',limits=c(0,5),ticks=0:5))
p<-os_panel_contract(praw,g,axes,population=list(cohort='synthetic',endpoint='score',horizon='visit',validation_scope='internal held-out'))
check(isTRUE(meta(os_compose(list(p,p),collect_guides=TRUE,shared_axes='both'))$definition$composition$effective),'same declared actual axes and entity mappings pass')
gbad<-g;gbad$group$values$one<-'#000000';bad(os_panel_contract(praw,gbad,axes),'contract cannot lie about rendered entity colour')
abad<-axes;abad$x$ticks<-c(0,2,4);bad(os_panel_contract(praw,g,abad),'contract cannot lie about actual axis ticks')
p2raw<-praw+ggplot2::scale_colour_manual(values=c(one='#000000',two='#D55E00',three='#009E73'));p2<-os_panel_contract(p2raw,gbad,axes)
bad(os_compose(list(p,p2)), 'same entity conflicting colours refused even with local guides')
galias<-g;galias$group$entity_type<-'different artificial endpoint';palias<-os_panel_contract(praw,galias,axes)
ca<-suppressWarnings(os_compose(list(p,palias),collect_guides=TRUE));check(!meta(ca)$definition$composition$effective && grepl('different entities',meta(ca)$definition$composition$reason),'same colours with different entities keep local legends')
cn<-suppressWarnings(os_compose(list(praw,praw),collect_guides=TRUE));check(!meta(cn)$definition$composition$effective,'missing semantic contracts cannot imply compatible guides')
bad(os_compose(list(p,praw),shared_axes='both'),'shared axes require contracts from every panel')
check(grepl('independent',meta(os_compose(list(p,p)))$caption,fixed=TRUE),'free axes and independent order explicitly disclosed')
check(identical(meta(os_compose(list(p,p)))$data$panels[[1]]$notes$panel_contract$population,meta(p)$notes$panel_contract$population),'cohort endpoint horizon and validation remain panel-specific')
# Null fields and exact 17-digit export survive repeated metadata merges.
q<-os_heatmap(m/7,'fraction','sequential',unit='fraction');qm<-meta(q)
q2<-os_with_meta(q,definition=qm$definition,notes=qm$notes)
check(identical(meta(q2)$definition,qm$definition) && identical(meta(q2)$notes,qm$notes),'complete matrix and panel contracts merge atomically including explicit NULLs')
bad(os_with_meta(q,definition=list(matrix_contract=NULL)),'matrix contract erasure refused')
bad(os_with_meta(q,definition=list(matrix_contract=list(version=OS_MATRIX_SEMANTIC_VERSION))),'partial matrix contract replacement refused')
for(j in c('nature','cell')) {
  for(n in c('states','masked','distance','composition')) {
    plot<-switch(n,states=ps,masked=p1,distance=pd,composition=co)
    saved<-os_finalize_figure(plot,file.path(out,paste(j,n,sep='-')),width='double',height_mm=100,journal=j,root=out)
    check(all(file.exists(c(saved$files$png,saved$files$pdf,saved$spec))),paste(j,n,'real R PDF/PNG/spec export'))
  }
}
save<-os_save_figure(q2,file.path(out,'precision'),formats='png',width='double',height_mm=90)
reread<-jsonlite::fromJSON(save$spec)
check(identical(reread$data$source_values$value,as.vector(m/7)),'matrix source values survive exact binary64 JSON roundtrip')
check(identical(reread$definition$matrix_contract$source_sha256,qm$definition$matrix_contract$source_sha256),'saved matrix source checksum retained')
cat('MATRIX_CHECKS',checks,'FAILED',length(failed),'\n');if(length(failed)) stop(paste(failed,collapse='; '));cat('ALL MATRIX SEMANTICS CHECKS PASSED\n')
